import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  IconButton,
  Typography,
  Box
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';
import BookAppointmentForm from './BookAppointmentForm';
import DocuSignModal from '../DocuSign/DocuSignModal';

const AppointmentModal = ({ open, onClose, onSubmit }) => {
  const [showDocuSign, setShowDocuSign] = useState(false);
  const [signingData, setSigningData] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleProceedToSign = async (data) => {
    console.log('Proceeding to DocuSign with data:', data);
    setSigningData(data);
    setShowDocuSign(true);
  };

  const handleSigningComplete = async (signedDocumentData) => {
    try {
      setIsSubmitting(true);
      console.log('Document signed successfully:', signedDocumentData);

      // Call the parent's onSubmit with the complete appointment data
      await onSubmit({
        ...signingData.appointment,
        documentSigned: true,
        signedAt: new Date().toISOString(),
        envelopeId: signedDocumentData?.envelopeId,
        status: 'SIGNED',
        documentUrl: signedDocumentData?.documentUrl
      });

      onClose();
    } catch (error) {
      console.error('Error handling signed document:', error);
    } finally {
      setIsSubmitting(false);
      setShowDocuSign(false);
    }
  };

  return (
    <>
      <DocuSignModal
        open={showDocuSign}
        onClose={() => setShowDocuSign(false)}
        onSigningComplete={handleSigningComplete}
        formData={signingData?.appointment}
        isSubmitting={isSubmitting}
      />

      <Dialog 
        open={open} 
        onClose={onClose}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: {
            borderRadius: 2,
            bgcolor: 'background.paper'
          }
        }}
      >
        <DialogTitle>
          <Box display="flex" justifyContent="space-between" alignItems="center">
            <Typography variant="h5" fontWeight={600}>
              Book an Appointment
            </Typography>
            <IconButton 
              onClick={onClose} 
              size="small"
              disabled={isSubmitting}
            >
              <CloseIcon />
            </IconButton>
          </Box>
        </DialogTitle>

        <DialogContent>
          <BookAppointmentForm 
            onProceedToSign={handleProceedToSign}
            onCancel={onClose}
            isSubmitting={isSubmitting}
          />
        </DialogContent>
      </Dialog>
    </>
  );
};

export default AppointmentModal;
